INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Line-Interactive-USV nur für große Server geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Für mittlere Anforderungen wie kleine Server"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Line-Interactive-USV?', 3, '[{"text": "Spannungsregulierung", "correct": true, "because": "Stabilisiert Stromversorgung"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Stromschutz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet eine Line-Interactive-USV?', 5, '[{"text": "Spannungsstabilisierung", "correct": true, "because": "Gleicht Schwankungen aus"}, {"text": "Batterie-Backup", "correct": true, "because": "Überbrückt Stromausfälle"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Line-Interactive-USV schützt kleine Server. b) Sie ist nur für kurzzeitige Ausfälle geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch längere Ausfälle möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Line-Interactive-USV?', 4, '[{"text": "Spannungsregulierung", "correct": false, "because": "Kernfunktion"}, {"text": "Batterielaufzeit", "correct": false, "because": "Wichtig für Backup"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Line-Interactive-USV auch Überspannungsschutz bietet?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt vor Spannungsspitzen"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft ist typisch für eine Line-Interactive-USV?', 3, '[{"text": "Automatische Spannungsregelung", "correct": true, "because": "Stabilisiert Strom"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Line-Interactive-USV?', 5, '[{"text": "Schutz bei Stromausfall", "correct": true, "because": "Batterie-Backup"}, {"text": "Spannungsausgleich", "correct": true, "because": "Gleicht Schwankungen aus"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Line-Interactive-USV ist kostengünstig. b) Sie ist für große Rechenzentren gedacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für mittlere Anforderungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Line-Interactive-USV?', 4, '[{"text": "Batterie", "correct": false, "because": "Notstromversorgung"}, {"text": "Spannungsregler", "correct": false, "because": "Stabilisiert Strom"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine Line-Interactive-USV nur bei Stromausfall?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei Spannungsschwankungen"}, {"text": "Ja", "correct": false, "because": "Mehr Schutzfunktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte eignen sich für eine Line-Interactive-USV?', 4, '[{"text": "Kleine Server", "correct": true, "because": "Mittlere Anforderungen"}, {"text": "Netzwerkgeräte", "correct": true, "because": "Stabile Stromversorgung"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Line-Interactive-USV nur kurzfristig schützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Laufzeit abhängig von Batterie"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
